import{_ as t,o as e,c as r,a2 as o}from"./chunks/framework.BWuWLRhz.js";const g=JSON.parse('{"title":"CZeroX 应用","description":"","frontmatter":{},"headers":[],"relativePath":"guide/app.md","filePath":"guide/app.md","lastUpdated":1785861127000}'),s={name:"guide/app.md"};function n(l,a,i,d,h,c){return e(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="czerox-应用" tabindex="-1">CZeroX 应用 <a class="header-anchor" href="#czerox-应用" aria-label="Permalink to &quot;CZeroX 应用&quot;">​</a></h1><p><strong>CZeroX</strong> 是 CZero 的原生配套应用，采用 Jetpack Compose 构建（Miuix 风格），直接读写模块的 <code>config.json</code> 与各份规则 JSON。它是模块唯一的图形化配置前端，无需 WebUI。</p><h2 id="下载" tabindex="-1">下载 <a class="header-anchor" href="#下载" aria-label="Permalink to &quot;下载&quot;">​</a></h2><p>在<a href="/download">下载页</a>或 <a href="https://github.com/Xocio/CZero/releases" target="_blank" rel="noreferrer">Releases</a> 获取最新版 APK。模块与应用建议保持同版本。</p><h2 id="三个标签页" tabindex="-1">三个标签页 <a class="header-anchor" href="#三个标签页" aria-label="Permalink to &quot;三个标签页&quot;">​</a></h2><p>应用底部分为 <strong>主页 / 存储 / 设置</strong> 三块。</p><h3 id="主页" tabindex="-1">主页 <a class="header-anchor" href="#主页" aria-label="Permalink to &quot;主页&quot;">​</a></h3><ul><li><strong>运行状态</strong> —— 调度进程的运行情况与内存占用；未在运行时可一键重启。</li><li><strong>清理统计</strong> —— 今日与累计释放的空间，以及各应用清理、空文件夹、压制、垃圾回收的执行次数。点击可进入<strong>清理趋势</strong>页，查看近 7 / 30 天的每日释放量。</li><li><strong>F2FS 状态</strong> —— 实时的段使用情况。</li><li><strong>一键操作</strong> —— 立即清理、单应用清理、后台压制、F2FS 垃圾回收、空文件夹清理。执行过程通过通知显示进度与结果，支持超级岛。</li></ul><h3 id="存储" tabindex="-1">存储 <a class="header-anchor" href="#存储" aria-label="Permalink to &quot;存储&quot;">​</a></h3><p>与清理无关、但同样关乎存储健康的面板：</p><ul><li><strong>器件寿命</strong> —— 显示 UFS / eMMC 的寿命等级与预留块预警，换算为剩余寿命区间。</li><li><strong>实时读写速率</strong> —— 当前读写曲线与累计读写量。</li><li><strong>性能测试</strong> —— 顺序读写、随机读写、数据库事务三类项目，给出综合评分。多轮结果波动过大时会提示重测。</li><li><strong>器件信息</strong> —— 类型、型号、厂商、固件与容量。</li></ul><div class="tip custom-block"><p class="custom-block-title">寿命数据为只读读取</p><p>寿命与器件信息均为只读读取，不会向存储器件写入任何数据。性能测试会实际读写测试文件，结束后自动清理。</p></div><h3 id="设置" tabindex="-1">设置 <a class="header-anchor" href="#设置" aria-label="Permalink to &quot;设置&quot;">​</a></h3><p>按分组覆盖 <code>config.json</code> 中的每一项，保存后即时生效，无需重启。</p><table tabindex="0"><thead><tr><th>分组</th><th>包含</th></tr></thead><tbody><tr><td><strong>清理</strong></td><td>基础清理、GC 清理、后台压制（及其目标应用名单）、空文件夹清理（及白名单）、增强清理、回收站</td></tr><tr><td><strong>规则</strong></td><td>自定义规则（内置规则 + 规则源）、清理白名单、应用缓存清理</td></tr><tr><td><strong>精细化压制</strong></td><td>压制开关与能力探测、压制应用名单</td></tr><tr><td><strong>其他</strong></td><td>日志、应用设置（语言 / 主题等）、备份与恢复</td></tr></tbody></table><h2 id="几个主要页面" tabindex="-1">几个主要页面 <a class="header-anchor" href="#几个主要页面" aria-label="Permalink to &quot;几个主要页面&quot;">​</a></h2><h3 id="规则编辑器与规则源" tabindex="-1">规则编辑器与规则源 <a class="header-anchor" href="#规则编辑器与规则源" aria-label="Permalink to &quot;规则编辑器与规则源&quot;">​</a></h3><p>管理自定义清理路径、清理白名单与空文件夹的清扫范围。规则按分组组织，可整组启停与排序。</p><p>除内置规则外，还可以订阅第三方<strong>规则源</strong>，添加后每天自动更新一次，在页面上呈现为一张独立卡片。发布规则源的方法见 <a href="/guide/rule-source">开发规则源</a>。</p><h3 id="应用缓存清理" tabindex="-1">应用缓存清理 <a class="header-anchor" href="#应用缓存清理" aria-label="Permalink to &quot;应用缓存清理&quot;">​</a></h3><p>按应用查看各条路径的实际占用并逐条增删；也可以从<strong>云端共享库</strong>拉取其他用户验证过的规则，或提交自己整理的规则等待审核。审核通过的规则会进入公开的规则快照，供所有用户获取。</p><h3 id="回收站" tabindex="-1">回收站 <a class="header-anchor" href="#回收站" aria-label="Permalink to &quot;回收站&quot;">​</a></h3><p>按次查看清理记录（文件数、大小、过期时间），并将误删的文件一键恢复至原位。被清理的文件默认保留 7 天，保留期可通过 <code>general.recycle_keep_days</code> 调整。详见<a href="/guide/features#回收站与恢复">功能详解 · 回收站与恢复</a>。</p><h3 id="精细化压制" tabindex="-1">精细化压制 <a class="header-anchor" href="#精细化压制" aria-label="Permalink to &quot;精细化压制&quot;">​</a></h3><p>压制后台应用而不结束进程，运行状态完整保留、切回时即时恢复。该页会先探测设备的支持情况（系统版本、内核支持、当前开关状态与实际处于压制态的进程数），对应 <code>config.json</code> 的 <code>freezer</code> 一节。</p><p>另有<strong>压制应用名单</strong>页，逐个列出各应用的进程数、已压制数与内存占用，可按需勾选。</p><div class="tip custom-block"><p class="custom-block-title">与主页「后台压制」的区别</p><p>主页一键操作中的后台压制会直接结束进程；此处为挂起而不结束。详见<a href="/guide/features#精细化压制">功能详解 · 精细化压制</a>。</p></div><h3 id="备份与恢复" tabindex="-1">备份与恢复 <a class="header-anchor" href="#备份与恢复" aria-label="Permalink to &quot;备份与恢复&quot;">​</a></h3><p>将配置与全部规则导出为单个文件，换机或重新刷入后一键导回。</p><h2 id="语言" tabindex="-1">语言 <a class="header-anchor" href="#语言" aria-label="Permalink to &quot;语言&quot;">​</a></h2><p>CZeroX 支持 <strong>简体中文</strong> 与 <strong>English</strong>，跟随系统或在应用内切换。</p><h2 id="与模块的关系" tabindex="-1">与模块的关系 <a class="header-anchor" href="#与模块的关系" aria-label="Permalink to &quot;与模块的关系&quot;">​</a></h2><p>CZeroX 本身不执行清理，只负责<strong>读写配置并展示状态</strong>，实际的调度与清理由模块完成。因此即使不安装 CZeroX，模块也能按默认配置正常工作 —— 应用的价值在于让配置与查看变得直观。</p>',33)])])}const u=t(s,[["render",n]]);export{g as __pageData,u as default};
